// === Tab: Link ===
class Link {
	constructor(r, ang, w, i) {
		this.r = r;
		this.ang = ang;
		this.oang = ang;
		this.w = w;
		this.id = i;
	}
	show() {
		noStroke();
		push();
		rotateX(-HALF_PI);
		if (this.ang >= 0 && this.ang <= PI) {
			rotateY(this.ang);
			translate(this.r, 0, 0);
			rotateY(HALF_PI);
		} else if (this.ang < 0 && this.ang >= -0.7 * PI) {
			translate(this.r, 0, 0);
			translate(0, 0, map(this.ang, 0, -PI, 0, 850));
			rotateY(HALF_PI);
		} else if (this.ang < -0.7 * PI && this.ang >= -1.71 * PI) {
			translate(0, 0, 595)
			rotateY(this.ang - 0.3 * PI);
			translate(-this.r, 0, 0);
			rotateY(HALF_PI);
		} else if (this.ang > PI) {
			translate(-this.r, 0, 0);
			translate(0, 0, map(this.ang, PI, TAU, 0, 940));
			rotateY(HALF_PI);
		}
		scale(0.37);
		metalness(5);
		shininess(2)
		if (this.w == 12) specularMaterial(255);
		else specularMaterial(100);
		push();
		translate(0, -this.w, 0)
		model(side);
		translate(0, 2 * this.w, 0);
		model(side);
		pop();
		if (this.w == 12) {
			push();
			translate(-65, 0, 0);
			fill(20);
			cylinder(15, 60);
			fill(120);
			cylinder(36, this.w * 1.3);
			translate(130, 0, 0);
			fill(20);
			cylinder(15, 60);
			fill(120);
			cylinder(36, this.w * 1.3);
			pop();
		}
		pop();
	}
}

// === Tab: Side ===
function makeSide() {
	fill(40);
	side = csg(() => box(100, 6, 60)).union(() => {
		push();
		translate(65, 0, 0);
		cylinder(45, 6, 24, 1);
		translate(-130, 0, 0);
		cylinder(45, 6, 24, 1);
		pop();
	}).subtract(() => {
		push();
		translate(0, 0, 75);
		cylinder(55, 100, 24, 1);
		pop();
		push();
		translate(0, 0, -75);
		cylinder(55, 100, 24, 1);
		pop();
	}).done();
}

// === Tab: Sprocket ===
function makeSprocket() {
	fill(255);
	noStroke();
	sprocket = csg(() => ellipsoid(300, 300, 10)).subtract(() => {
		for (i = 0; i < 36; i++) {
			a = TAU / 36;
			rotateZ(a);
			push();
			translate(300, 0, 0);
			rotateX(HALF_PI);
			cylinder(20, 15);
			pop();
		}
		for (i = 0; i < 12; i++) {
			a = TAU / 12;
			rotateZ(a);
			push();
			if (i % 2 == 0) translate(225, 0, 0);
			else translate(150, 0, 0)
			rotateX(HALF_PI);
			cylinder(20, 50);
			pop();
		}
		rotateX(HALF_PI);
		cylinder(40, 50, 7, 1);
	}).done();
}

// === Tab: mySketch ===
var side, sprocket;
var links = []
var ang = 0;
var av = 0.05;
var lpos;

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	lpos = createVector(0, 0);
	makeSide();
	makeSprocket();
	for (i = 0; i < 60; i += 1) {
		let a = -3 * HALF_PI + i * PI / 18;
		let w = 12 + (i % 2) * 8;
		let link = new Link(280, a, w, i);
		links.push(link);
	}
}

function draw() {
	background(0);
	ambientLight(120);
	lpos.lerp(createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - width / 2, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - 3 * height / 2), 0.1);
	pointLight(80, 80, 80, lpos.x, lpos.y, height / 2);
	orbitControl();
	rotateX(-QUARTER_PI);
	rotateZ(-HALF_PI);
	translate(0, -300, 0);
	push();
	rotateZ(PI / 36 + ang);
	metalness(3);
	shininess(2);
	specularMaterial(255);
	scale(0.95);
	model(sprocket);
	pop();
	push();
	translate(0, 600, 0);
	rotateZ(PI / 22 + ang);
	metalness(3);
	shininess(2);
	specularMaterial(255);
	scale(0.95);
	model(sprocket);
	pop();

	for (link of links) {
		link.ang = link.oang - ang;
		if (link.ang < -1.70 * PI) {
			link.oang = links[links.length - 1].oang + PI / 18;
			links.push(links.shift());
		}
	}
	for (link of links) {
		link.show();
	}
	ang += av;
	if (keyIsDown(32) || ((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {
		av += 0.002;
	}
	av *= 0.95;
}
